<script setup lang="ts">
import { computed, ref } from 'vue';import { Bell, Coffee, ShieldCheck, Download, Trash2, CheckCheck, Clock3, Power, Monitor, Volume2 } from 'lucide-vue-next';import { useAppStore,duration,dateLabel,stateLabels } from '../store';import { platforms } from '../../../shared/platforms';import type { Settings } from '../../../shared/contracts';import Modal from '../components/Modal.vue'
const store=useAppStore();const confirmClear=ref(false),confirmQuit=ref(false);const settings=computed(()=>store.data!.settings);const finished=computed(()=>store.tasks.filter(t=>['finished','cancelled'].includes(t.status)).slice().sort((a,b)=>b.updatedAt-a.updatedAt));const tab=ref('reminders')
async function update(value:Partial<Pick<Settings,'muteAll'|'audiblePlatform'|'closeToTray'|'reminderEnabled'|'reminderTime'|'breakEnabled'|'breakMinutes'>>){await store.run({type:'settings.update',settings:value},'设置已保存在本机')}
</script>
<template><div class="page"><div class="page-heading"><div><p class="eyebrow">YOUR RHYTHM</p><h1>学习记录与设置</h1><p class="subtitle">让学习适合你的节奏，所有设置与记录留在本机。</p></div></div><div class="segmented-tabs"><button v-for="item in [{id:'reminders',label:'学习提醒'},{id:'records',label:'学习记录'},{id:'settings',label:'应用设置'}]" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{item.label}}</button></div>
 <template v-if="tab==='reminders'"><section class="panel settings-panel"><div class="setting-row"><span class="setting-icon blue"><Bell :size="22"/></span><div class="grow"><h3>每天的学习提醒</h3><p>只提醒，不会自动启动课程。</p></div><input type="time" aria-label="每天学习提醒时间" :value="settings.reminderTime" @change="update({reminderTime:($event.target as HTMLInputElement).value})"/><button class="switch" role="switch" aria-label="开启每天学习提醒" :aria-checked="settings.reminderEnabled" :class="{on:settings.reminderEnabled}" @click="update({reminderEnabled:!settings.reminderEnabled})"><i></i></button></div><div class="setting-row"><span class="setting-icon teal"><Coffee :size="22"/></span><div class="grow"><h3>记得休息一下</h3><p>按去重后的观察播放时间提醒，三个平台不重复计时。</p></div><select aria-label="休息提醒间隔" :value="settings.breakMinutes" @change="update({breakMinutes:Number(($event.target as HTMLSelectElement).value)})"><option v-for="m in [15,25,30,45,60,90]" :key="m" :value="m">每 {{m}} 分钟</option></select><button class="switch" role="switch" aria-label="开启休息提醒" :aria-checked="settings.breakEnabled" :class="{on:settings.breakEnabled}" @click="update({breakEnabled:!settings.breakEnabled})"><i></i></button></div><div class="settings-note">应用完全退出后不会发送提醒。下次打开会汇总启用后错过的学习提醒（含跨天）；系统通知被关闭时，你仍可在下方查看。</div></section><section class="panel notice-panel"><div class="section-heading"><h2>提醒记录</h2><button class="text-button" @click="store.run({type:'notices.read'})"><CheckCheck :size="16"/>全部已读</button></div><div v-if="!store.notices.length" class="quiet-state"><Bell :size="25"/><p>暂时没有提醒。开始学习后，重要的消息会留在这里。</p></div><div v-for="n in store.notices" :key="n.id" :class="['notification-row',{unread:!n.read}]"><span class="status-dot" v-if="!n.read"></span><div class="grow"><strong>{{n.title}}</strong><p>{{n.body}}</p></div><small>{{dateLabel(n.createdAt)}}</small></div></section></template>
 <template v-else-if="tab==='records'"><div class="record-stats"><div class="panel"><p>今日累计播放时间</p><h2>{{duration(store.data!.stats.playbackMs)}}</h2><small>多路视频各自累计，仅统计观察到的播放片段</small></div><div class="panel"><p>今日去重后的播放时间</p><h2>{{duration(store.data!.stats.elapsedMs)}}</h2><small>重叠区间只算一次，不代表平台认可的有效学时</small></div></div><section class="panel"><div class="panel-padding"><h2>已结束的任务</h2></div><div v-if="!finished.length" class="empty-small">还没有已结束的学习任务。</div><div v-for="t in finished" :key="t.id" class="record-row"><div class="grow"><h3>{{t.title}}</h3><p>{{store.accountLabel(t.accountId)}} · {{dateLabel(t.updatedAt)}}</p><small>{{t.reason}}</small></div><span class="badge neutral">{{stateLabels[t.status]}}</span><span :class="['badge',t.platformCompletion==='complete'?'green':'amber']">{{t.platformCompletion==='complete'?'平台已确认':'平台完成待确认'}}</span></div></section></template>
 <template v-else><section class="panel settings-panel"><div class="setting-row"><span class="setting-icon blue"><Monitor :size="22"/></span><div class="grow"><h3>关闭窗口后留在托盘</h3><p>尝试继续播放；不支持后台播放时暂停提示。不伪装前台状态。</p></div><button class="switch" role="switch" aria-label="关闭窗口后留在托盘" :aria-checked="settings.closeToTray" :class="{on:settings.closeToTray}" @click="update({closeToTray:!settings.closeToTray})"><i></i></button></div><div class="setting-row"><span class="setting-icon teal"><Volume2 :size="22"/></span><div class="grow"><h3>允许发声的平台</h3><p>同时播放时，其他平台保持静音。</p></div><select aria-label="允许发声的平台" :value="settings.audiblePlatform" @change="update({audiblePlatform:($event.target as HTMLSelectElement).value as Settings['audiblePlatform']})"><option v-for="p in platforms" :key="p.id" :value="p.id">{{p.name}}</option></select></div></section><section class="panel settings-panel"><div class="setting-row"><span class="setting-icon teal"><ShieldCheck :size="22"/></span><div class="grow"><h3>本地隐私与诊断</h3><p>不上传遥测。导出内容不含密码、Cookie、页面正文或课程名称。</p></div><button class="button compact" @click="store.run({type:'diagnostics.export'},'诊断导出操作已结束')"><Download :size="16"/>导出诊断</button></div><div class="setting-row"><span class="setting-icon amber"><Trash2 :size="22"/></span><div class="grow"><h3>清理学习历史</h3><p>删除已结束任务、学习时长、提醒及日志，保留账号和未结束任务。</p></div><button class="button compact" @click="confirmClear=true">清理记录</button></div></section><section class="panel compatibility-panel"><h2>平台兼容性</h2><p class="muted">当前版本已实现候选适配器，但尚未完成真实账号和课程验收。请勿将测试夹具的通过结果视为真实兼容。</p><div v-for="p in platforms" :key="p.id" class="compatibility-row"><strong>{{p.name}}</strong><span class="grow">{{p.scope}}</span><span class="badge amber">待真实课程验证</span></div></section><div class="exit-row"><p>v{{store.data!.version}} · 本地试用版 · 手动安装更新</p><button class="button" @click="confirmQuit=true"><Power :size="16"/>完全退出应用</button></div></template>
 <Modal v-if="confirmClear" title="清理本地学习历史？" @close="confirmClear=false"><p>这将删除已结束任务、时长统计、提醒记录和诊断日志。账号登录、课程缓存和未结束任务会保留。</p><div class="modal-actions"><button class="button" @click="confirmClear=false">取消</button><button class="button danger-solid" @click="store.run({type:'data.clear-history'},'学习历史已清理');confirmClear=false">确认清理</button></div></Modal><Modal v-if="confirmQuit" title="完全退出网课助手？" @close="confirmQuit=false"><p>播放将停止，检查点会保存。退出后不会发送学习提醒；下次打开时需要确认恢复任务。</p><div class="modal-actions"><button class="button" @click="confirmQuit=false">继续使用</button><button class="button primary" @click="store.run({type:'app.quit'})">保存并退出</button></div></Modal>
</div></template>
